using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Reflection;using UnityEngine;using UnityEngine.SceneManagement;using UnityEngine.InputSystem;using UnityEngine.InputSystem.LowLevel;using UnityEditor;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class BMPlay {
 static string O=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../../Docs/Review/2026-11-09_B2_FullFloor/"));static GameObject player;static MonoBehaviour look;static Transform pivot;static Vector3 savedPosition,from;static Quaternion savedYaw,savedPitch;static bool savedLook,running;static int moveEvents;static InputAction moveAction;static int stage,first,last;static double start;static InputSettings.BackgroundBehavior bg;static InputSettings.EditorInputBehaviorInPlayMode eb;static List<object> results=new List<object>();static List<string> errors=new List<string>();static List<float> frameTimes=new List<float>();
 public static object Prepare(){if(Application.isPlaying||SceneManager.GetActiveScene().isDirty)throw new Exception("Saved edit required");SessionState.SetBool("BMPlay.Background",Application.runInBackground);Application.runInBackground=true;return new{mouse=Mouse.current.enabled,keyboard=Keyboard.current.enabled};}
 public static object Begin(){if(!Application.isPlaying||!SceneManager.GetActiveScene().path.EndsWith("Level_B2_Circular.unity"))throw new Exception("B2 Play required");if(!Mouse.current.enabled||!Keyboard.current.enabled)throw new Exception("Native device disabled");player=SceneManager.GetActiveScene().GetRootGameObjects().Single(g=>g.name.StartsWith("Player"));look=player.GetComponentsInChildren<MonoBehaviour>(true).Single(c=>c.GetType().Name=="PlayerLook");pivot=(Transform)look.GetType().GetField("cameraRoot",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(look);savedPosition=player.transform.position;savedYaw=player.transform.rotation;savedPitch=pivot.localRotation;savedLook=look.enabled;look.enabled=false;pivot.localRotation=Quaternion.identity;bg=InputSystem.settings.backgroundBehavior;eb=InputSystem.settings.editorInputBehaviorInPlayMode;InputSystem.settings.backgroundBehavior=InputSettings.BackgroundBehavior.IgnoreFocus;InputSystem.settings.editorInputBehaviorInPlayMode=InputSettings.EditorInputBehaviorInPlayMode.AllDeviceInputAlwaysGoesToGameView;EditorWindow.GetWindow(typeof(Editor).Assembly.GetType("UnityEditor.GameView")).Focus();results.Clear();errors.Clear();moveEvents=0;moveAction=player.GetComponent<PlayerInput>().actions.FindAction("Player/Move",true);moveAction.performed+=OnMoveRead;running=true;stage=0;Next();InputSystem.onAfterUpdate+=BeforeInput;EditorApplication.update+=Tick;Application.logMessageReceived+=Log;AssemblyReloadEvents.beforeAssemblyReload+=Cancel;EditorApplication.playModeStateChanged+=Mode;return new{started=true,stages=4};}
 static void Next(){var cc=player.GetComponent<CharacterController>();var starts=new[]{new Vector3(35.5f,-34,17.5f),new Vector3(-18,-34,4.3f),new Vector3(-124,-34,8f),new Vector3(-44.96f,-34,25.65f)};var yaws=new[]{-140f,90f,90f,0f};var plan=JObject.Parse(File.ReadAllText(Path.GetFullPath(Path.Combine(Application.dataPath,"../../../SourceAssets/B2_FullFloor/layout.json"))));var path=plan["tunnels"].First(t=>(string)t["id"]=="B2-T01")["path"];int mid=path.Count()/2;starts[0]=new Vector3((float)path[mid][0],-34,-(float)path[mid][1]);var next=new Vector3((float)path[mid+1][0],-34,-(float)path[mid+1][1]);yaws[0]=Quaternion.LookRotation(next-starts[0]).eulerAngles.y;cc.enabled=false;player.transform.SetPositionAndRotation(starts[stage]+Vector3.up*(cc.height*.5f-cc.center.y+.05f),Quaternion.Euler(0,yaws[stage],0));cc.enabled=true;Physics.SyncTransforms();from=player.transform.position;first=last=Time.frameCount;start=EditorApplication.timeSinceStartup;frameTimes.Clear();}
 static void OnMoveRead(InputAction.CallbackContext c){moveEvents++;} static void Log(string m,string st,LogType t){if(t==LogType.Error||t==LogType.Exception)errors.Add(m);}
