 static void BeforeInput(){if(running&&InputState.currentUpdateType!=InputUpdateType.Editor)InputState.Change(Keyboard.current,Time.frameCount-first<45?new KeyboardState(Key.W):new KeyboardState());} static void Tick(){try{if(!Application.isPlaying){End(false);return;}EditorApplication.QueuePlayerLoopUpdate();double elapsed=EditorApplication.timeSinceStartup-start;if(Time.frameCount!=last){last=Time.frameCount;if(elapsed>1)frameTimes.Add(Time.unscaledDeltaTime*1000);}if(Time.frameCount-first<180&&elapsed<15)return;var delta=player.transform.position-from;var cc=player.GetComponent<CharacterController>();var ms=frameTimes.OrderBy(x=>x).ToArray();results.Add(new{stage,name=new[]{"pipe_tunnel","centrifuge_bypass","backup_power","stair_lobby"}[stage],frames=Time.frameCount-first,distance=new Vector2(delta.x,delta.z).magnitude,rise=delta.y,grounded=cc.isGrounded,moveEvents,medianMs=ms.Length>0?ms[ms.Length/2]:0,mouse=Mouse.current.enabled,keyboard=Keyboard.current.enabled,camera=Camera.main?Camera.main.transform.position.ToString():null});stage++;if(stage<4)Next();else End(true);}catch(Exception e){errors.Add(e.ToString());End(false);}}
 static void End(bool complete){running=false;InputSystem.onAfterUpdate-=BeforeInput;if(moveAction!=null)moveAction.performed-=OnMoveRead;EditorApplication.update-=Tick;Application.logMessageReceived-=Log;AssemblyReloadEvents.beforeAssemblyReload-=Cancel;EditorApplication.playModeStateChanged-=Mode;try{InputSystem.QueueStateEvent(Keyboard.current,new KeyboardState());File.WriteAllText(O+"play.json",JsonConvert.SerializeObject(new{complete,results,errors,mouse=Mouse.current.enabled,keyboard=Keyboard.current.enabled},Formatting.Indented));}finally{InputSystem.settings.backgroundBehavior=bg;InputSystem.settings.editorInputBehaviorInPlayMode=eb;if(player){var cc=player.GetComponent<CharacterController>();bool on=cc.enabled;cc.enabled=false;player.transform.SetPositionAndRotation(savedPosition,savedYaw);cc.enabled=on;}if(pivot)pivot.localRotation=savedPitch;if(look)look.enabled=savedLook;}}
